// DeleteCosts answers what the delete of one row of each of the Members auth's tables
// a tenant's delete takes costs in a commit, as the schema read at generation tells it:
// the delete and an entry out of each of the table's indexes besides its key, with no
// change record, since the declarations write none. The withdrawal of an invitation costs
// the columns ConsumeMailLink writes and an entry of each index that holds one of them. A
// table the schema does not hold costs nothing (identity.Store.DeleteCosts).
func (store) DeleteCosts() identity.TenantDeleteCosts {
	return identity.TenantDeleteCosts{
		Membership:       resource.DeleteCost{IndexEntries: 1}.Mutations(false),
		Role:             resource.DeleteCost{IndexEntries: 0}.Mutations(false),
		Identity:         resource.DeleteCost{IndexEntries: 3}.Mutations(false),
		User:             resource.DeleteCost{IndexEntries: 3}.Mutations(false),
		RecordMembership: resource.DeleteCost{IndexEntries: 1}.Mutations(true),
		Invitation:       4,
		SessionEnd:       3,
	}
}

// RowsWithUser counts what the database's own rules add to the delete of the user's row,
// in mutations: each row of each table that hangs on the user by a foreign key declared
// ON DELETE CASCADE, as the schema read at generation holds them, with an entry out of
// each of that table's indexes, counted in the caller's transaction
// (identity.Store.RowsWithUser). The tables: MembersSessionIdentities, MembersSessionMailLinks, MembersSessionTrustedDevices.
func (store) RowsWithUser(ctx context.Context, txn resource.ReadWriteTransaction, userID impulse.UUID) (int, error) {
	stmt := spanner.Statement{
		SQL:    "SELECT (SELECT COUNT(*) FROM MembersSessionIdentities c0 WHERE c0.UserId = @userId), (SELECT COUNT(*) FROM MembersSessionMailLinks c0 WHERE c0.UserId = @userId), (SELECT COUNT(*) FROM MembersSessionTrustedDevices c0 WHERE c0.UserId = @userId)",
		Params: map[string]any{"userId": userID.String()},
	}
	costs := []int{
		resource.DeleteCost{IndexEntries: 3}.Mutations(false),
		resource.DeleteCost{IndexEntries: 4}.Mutations(false),
		resource.DeleteCost{IndexEntries: 3}.Mutations(false),
	}
	rows := 0
	if err := txn.SpannerReadOnlyTransaction().Query(ctx, stmt).Do(func(row *spanner.Row) error {
		for i, cost := range costs {
			var count int64
			if err := row.Column(i, &count); err != nil {
				return errors.Wrap(err, "spanner.Row.Column()")
			}
			rows += int(count) * cost
		}

		return nil
	}); err != nil {
		return 0, errors.Wrap(err, "spanner.RowIterator.Do()")
	}

	return rows, nil
}

// DirectoryOutsiders lists the people of the Members auth who hold a role in the
// sector, in it or in every sector, and have no sign-in through its directory: the
// people the sector's directory-only switch keeps out while it is on, and who turning
// it on would shut out. A super administrator is never one of them. It reads the
// sector's own list of its people (MembersSectorUser, whose OutsideDirectory column is the
// fact), in the caller's transaction, by username. The warning of the generated method
// that turns the switch on asks every auth's client
// (resource.TenantDirectoryRules.DirectoryOnlyWarning, through resource.DirectoryPeople),
// and it sits beside the store because it reads the auth's tables as the store does,
// through the declarations' own query types.
func (c *Client) DirectoryOutsiders(ctx context.Context, txn resource.ReadWriteTransaction, tenant accesstypes.Domain) ([]resource.DirectoryOutsider, error) {
	query := membersresources.NewMembersSectorUserQuery().
		AddColumns(membersresources.NewMembersSectorUserColumns().ID().Username().Name()).
		Where(membersresources.NewMembersSectorUserQueryClause().DomainID().Equal(string(tenant)).And().OutsideDirectory().Equal(true))
	outsiders := []resource.DirectoryOutsider{}
	for row, err := range query.List(ctx, txn) {
		if err != nil {
			return nil, errors.Wrap(err, "membersresources.MembersSectorUserQuery.List()")
		}
		outsiders = append(outsiders, resource.DirectoryOutsider{UserID: row.Data.ID, Username: row.Data.Username, Name: row.Data.Name})
	}

	return outsiders, nil
}

// SeatedCount counts the people of the Members auth in the sector's own
// list of its people (MembersSectorUser): who holds a role in the sector, in it or in
// every sector, and, where the sector has a directory, who signs in through it,
// one row a person, the list DirectoryOutsiders reads, in the caller's transaction. The
// read of the sector's directory-only switch says it beside the people
// DirectoryOutsiders counts (resource.TenantDirectoryRules.CountedBy), so a page that
// shows the switch says how many of the sector's people it keeps out.
func (c *Client) SeatedCount(ctx context.Context, txn resource.ReadWriteTransaction, tenant accesstypes.Domain) (int, error) {
	query := membersresources.NewMembersSectorUserQuery().
		AddColumns(membersresources.NewMembersSectorUserColumns().ID()).
		Where(membersresources.NewMembersSectorUserQueryClause().DomainID().Equal(string(tenant)))
	seated := 0
	for _, err := range query.List(ctx, txn) {
		if err != nil {
			return 0, errors.Wrap(err, "membersresources.MembersSectorUserQuery.List()")
		}
		seated++
	}

	return seated, nil
}

